{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "/ds_salaries.csv"
  },
  "title": "图1: 全球数据科学平均薪资热力图",
  "width": 800,
  "height": 500,
  "layer": [
    {
      "data": {
        "url": "https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json",
        "format": {
          "type": "topojson",
          "feature": "countries"
        }
      },
      "mark": {
        "type": "geoshape",
        "fill": "#e0e0e0",
        "stroke": "white"
      }
    },
    {
      "transform": [
        {
          "aggregate": [{"op": "mean", "field": "salary_in_usd", "as": "avg_salary"}],
          "groupby": ["company_location"]
        },
        {
          "lookup": "company_location",
          "from": {
            "data": {
              "url": "https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json",
              "format": {
                "type": "topojson",
                "feature": "countries"
              }
            },
            "key": "properties.iso_a2"
          },
          "as": "geo"
        },
        {
          "filter": "datum.geo"
        }
      ],
      "mark": {
        "type": "geoshape",
        "stroke": "white"
      },
      "encoding": {
        "shape": {"field": "geo", "type": "geojson"},
        "color": {
          "field": "avg_salary",
          "type": "quantitative",
          "scale": {"scheme": "viridis"},
          "title": "平均薪资 (USD)"
        },
        "tooltip": [
          {"field": "company_location", "type": "nominal", "title": "国家代码"},
          {"field": "avg_salary", "type": "quantitative", "title": "平均薪资", "format": "$,.0f"}
        ]
      }
    }
  ]
}

